package com.rezoxnemesis.videostudio;
import android.content.Context;import org.json.*;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.util.UUID;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=33,manifest=Config.NONE)
public class SketchCoverageTest {
 @Test public void declaredFramesDoNotHideEmptyCelsOrPretendRepeatedArtworkIsNewMotion() throws Exception {
  Context c=RuntimeEnvironment.getApplication();String id=UUID.randomUUID().toString();SketchEditOps.execute(c,"sketch_create",new JSONObject().put("sketchId",id).put("operationId","create").put("frameCount",200));JSONArray ops=new JSONArray();for(int frame=0;frame<3;frame++)ops.put(new JSONObject().put("type","add_object").put("layerId","layer_1").put("object",new JSONObject().put("id","cel_"+frame).put("kind","ellipse").put("frame",frame).put("exposure",1).put("fill",true).put("bounds",new JSONObject().put("x",.2).put("y",.2).put("width",.2).put("height",.2))));SketchEditOps.execute(c,"sketch_edit",new JSONObject().put("sketchId",id).put("operationId","poses").put("expectedRevision",1).put("operations",ops));
  JSONObject report=SketchEditOps.execute(c,"sketch_inspect",new JSONObject().put("sketchId",id).put("expectedRevision",2).put("frameOffset",0).put("frameLimit",4).put("characterLayerIds",new JSONArray().put("layer_1")));assertEquals(200,report.getInt("frameCount"));assertEquals(4,report.getJSONArray("frames").length());assertTrue(report.getBoolean("moreFrames"));JSONArray frames=report.getJSONArray("frames");assertEquals(1,frames.getJSONObject(0).getInt("exposedObjects"));assertFalse("New IDs and frame numbers cannot certify pose changes",frames.getJSONObject(1).getBoolean("contentChanged"));assertEquals(0,frames.getJSONObject(3).getInt("exposedObjects"));assertFalse(report.getBoolean("creativeQualityVerified"));assertFalse(report.getBoolean("articulatedMotionVerified"));assertEquals(3,report.getJSONObject("usage").getInt("objects"));assertEquals(4093,report.getJSONObject("remainingBudget").getInt("objects"));
 }
}
